import sys

def main():
    data = sys.stdin.read().strip()
    n = len(data) // 3
    suits = {'C': [], 'E': [], 'U': [], 'P': []}
    for i in range(n):
        card = data[i*3:(i+1)*3]
        num = int(card[:2])
        suit = card[2]
        suits[suit].append(num)
    out = []
    for s in 'CEUP':
        cards = suits[s]
        if len(cards) != len(set(cards)):
            out.append("erro")
        else:
            out.append(str(13 - len(cards)))
    sys.stdout.write('\n'.join(out) + '\n')

main()
